namespace Pekspro.RadioStorm.GeneralDatabase;

/// <summary>
/// Reflection-free bulk maps for the general database tables.
/// Must be kept in sync with <see cref="GeneralDatabaseContext"/> and its migrations.
/// </summary>
internal static class GeneralDatabaseBulkMaps
{
    public static SqliteBulkMap<DownloadState> DownloadStateMap { get; } = new DownloadStateBulkMap();

    // EpisodeId is configured as value generated by EF convention, but it holds a real
    // episode id and must therefore always be written.
    private sealed class DownloadStateBulkMap() : SqliteBulkMap<DownloadState>(
        nameof(DownloadState),
        [nameof(DownloadState.EpisodeId)],
        [
            nameof(DownloadState.EpisodeId),
            nameof(DownloadState.ProgramId),
            nameof(DownloadState.DownloadStatus),
        ])
    {
        public override void WriteValues(DownloadState e, Span<object?> v)
        {
            v[0] = e.EpisodeId;
            v[1] = e.ProgramId;
            v[2] = (int)e.DownloadStatus;
        }
    }
}
